-- Baseline is deliberately idempotent so existing V1 databases retain their data.
CREATE TABLE IF NOT EXISTS product (id VARCHAR(100) PRIMARY KEY, owner_id VARCHAR(100), payload TEXT NOT NULL, version INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS customer_order (id VARCHAR(100) PRIMARY KEY, owner_id VARCHAR(100) NOT NULL, payload TEXT NOT NULL, version INT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_order_owner ON customer_order(owner_id);
CREATE TABLE IF NOT EXISTS conversation (id VARCHAR(100) PRIMARY KEY, owner_id VARCHAR(100) NOT NULL, payload TEXT NOT NULL, version INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS chat_message (id VARCHAR(100) PRIMARY KEY, owner_id VARCHAR(100) NOT NULL, conversation_id VARCHAR(100) NOT NULL, payload TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_message_conversation ON chat_message(conversation_id,created_at);
CREATE TABLE IF NOT EXISTS agent_run (id VARCHAR(100) PRIMARY KEY, owner_id VARCHAR(100) NOT NULL, conversation_id VARCHAR(100) NOT NULL, status VARCHAR(30) NOT NULL, payload TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_run_owner ON agent_run(owner_id,created_at);
CREATE TABLE IF NOT EXISTS run_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, run_id VARCHAR(100) NOT NULL, event_type VARCHAR(40) NOT NULL, payload TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_event_run ON run_event(run_id,id);
CREATE TABLE IF NOT EXISTS graph_checkpoint (thread_id VARCHAR(100) NOT NULL, checkpoint_id VARCHAR(100) NOT NULL, payload TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(thread_id,checkpoint_id));
CREATE TABLE IF NOT EXISTS escalation_ticket (id VARCHAR(100) PRIMARY KEY, owner_id VARCHAR(100) NOT NULL, conversation_id VARCHAR(100) NOT NULL, status VARCHAR(30) NOT NULL, payload TEXT NOT NULL, version INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS refund_request (id VARCHAR(100) PRIMARY KEY, owner_id VARCHAR(100) NOT NULL, order_id VARCHAR(100) NOT NULL UNIQUE, idempotency_key VARCHAR(180) NOT NULL UNIQUE, amount NUMERIC(12,2) NOT NULL, status VARCHAR(30) NOT NULL, reason VARCHAR(500) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS knowledge_chunk (id VARCHAR(100) PRIMARY KEY, source VARCHAR(300) NOT NULL, heading VARCHAR(300) NOT NULL, content TEXT NOT NULL, content_hash VARCHAR(100) NOT NULL, vector_text TEXT NOT NULL);
